/* Minimal offline PDFObject stub
   This implements PDFObject.embed(url, target, options) enough for the app
   to display a PDF in an iframe or a new window when running offline.
*/
var PDFObject = (function () {
  function embed(urlOrDataUrl, target, options) {
    try {
      // If target is a selector string, find element; if omitted open new window
      var container = null;
      if (typeof target === 'string') container = document.querySelector(target);
      else if (target instanceof Element) container = target;

      var iframe = document.createElement('iframe');
      iframe.style.width = (options && options.width) || '100%';
      iframe.style.height = (options && options.height) || '100%';
      iframe.style.border = '0';
      iframe.src = urlOrDataUrl;

      if (container) {
        // replace existing content
        while (container.firstChild) container.removeChild(container.firstChild);
        container.appendChild(iframe);
        return container;
      }

      // fallback: open in new window
      var w = window.open('', '_blank');
      if (!w) return false;
      w.document.body.style.margin = '0';
      w.document.body.appendChild(iframe);
      return w;
    } catch (e) {
      return false;
    }
  }

  return { embed: embed };
})();
